<script setup lang="ts">import {ref,onMounted} from 'vue';import {request} from '../api/client';import type {Audit} from '../types/domain';import {useTask} from '../hooks/useTask';import {date} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const rows=ref<Audit[]>([]),{error,perform}=useTask();async function load(){rows.value=await request<Audit[]>('/audit');}onMounted(()=>perform(load));</script><template><PageHeading index="06" title="每份研究，保留可核对的来路" text="记录最近100次数据、模型、假设写入与交付请求；权限拒绝也会留下状态。"><button class="outline" @click="perform(load)">刷新研究留痕 ↻</button></PageHeading><ErrorNotice :message="error" @retry="perform(load)"/><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作账号</th><th>动作</th><th>请求状态</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td>{{date(a.created_at)}}</td><td>{{a.actor}}</td><td><code>{{a.action}}</code></td><td :class="a.status_code<400?'positive':'negative'">{{a.status_code}}</td></tr></tbody></table></div></template>
